import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { compileSchema, schemaDiagnostics } from "./schema-core.mjs";

export { schemaDiagnostics };

/**
 * The schema this package ships (data/profile-v0.schema.json), so the default works wherever the package is
 * installed. It is a copy of the repository's spec/profile-v0.schema.json (W0's shared contract), regenerated by
 * `npm run data -w packages/resolver`; test/data.test.mjs fails when the copy is stale.
 */
export const DEFAULT_SCHEMA_PATH = fileURLToPath(new URL("../data/profile-v0.schema.json", import.meta.url));

/**
 * The validate function for the profile schema, with ajv's `errors`. The shipped schema (the default, or a document or
 * file equal to it) gets the validator compiled ahead of time; any other schema is compiled by ajv at run time.
 *
 * @param schema a path to the schema file (default: the copy this package ships), or the schema document itself
 *               (`import schema from "@meantjs/profile/schema.json" with { type: "json" }` is the same copy).
 */
export async function createSchemaValidator(schema = DEFAULT_SCHEMA_PATH) {
  return compileSchema(typeof schema === "string" ? JSON.parse(await readFile(schema, "utf8")) : schema);
}
